-- Repository baseline, 2026-09-29. Existing databases require an explicit, audited baseline.
create table activity_logs (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), result varchar(10) not null check ((result in ('SUCCESS','FAILURE'))), id uuid not null, user_id uuid, action varchar(40) not null check ((action in ('LOGIN','LOGIN_FAILED','LOGOUT','PASSWORD_CHANGED','PASSWORD_RESET','ACCOUNT_REGISTERED','PROFILE_UPDATED','ACCOUNT_DELETE_REQUESTED','ACCOUNT_RESTORED','SOCIAL_CONNECTED','SOCIAL_DISCONNECTED','CONTENT_CREATED','CONTENT_UPDATED','CONTENT_DELETED','CONTENT_STATUS_CHANGED','SCHEDULE_CREATED','SCHEDULE_UPDATED','SCHEDULE_CANCELLED','POST_PUBLISHED','POST_FAILED','PLAN_CHANGED','PAYMENT_SUCCEEDED','PAYMENT_FAILED','PAYMENT_WEBHOOK_REJECTED','PAYMENT_CANCELLED','PAYMENT_MARKED_PAID','SUBSCRIPTION_ADJUSTED','USER_CREATED','USER_UPDATED','USER_STATUS_CHANGED','USER_DELETED','USER_PASSWORD_RESET','PLAN_CONFIG_UPDATED','LANDING_CONTENT_UPDATED','LANDING_CONTENT_PUBLISHED','AI_CONFIG_UPDATED','API_VERSION_UPDATED','TOKENS_GRANTED','USAGE_RESET','BILLING_RATE_CREATED','ALERT_ACKED','ALERT_CONFIG_UPDATED','USAGE_META_VIEWED','USER_SESSIONS_VIEWED','DEV_CREDIT_GRANTED','DATA_EXPORTED'))), ip varchar(45), target_type varchar(60), target_id varchar(100), user_agent varchar(300), metadata text, user_email_snapshot varchar(255), primary key (id));
create table ai_config_audit (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), actor_user_id uuid, entity_id uuid not null, id uuid not null, action varchar(30) not null check ((action in ('CREATE','UPDATE','DELETE','TEST_CONNECTION','SYNC_MODELS','RESET_MODEL_HEALTH'))), entity_type varchar(40) not null, after_snapshot jsonb, before_snapshot jsonb, primary key (id));
create table ai_model_price_catalog (input_price_per_1m numeric(12,4), output_price_per_1m numeric(12,4), created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, provider_code varchar(30) not null check ((provider_code in ('ANTHROPIC','GOOGLE','UNKNOWN'))), model_code varchar(100) not null, primary key (id));
create table ai_models (enabled boolean not null, input_price_per_1m numeric(12,4), max_tokens integer, output_price_per_1m numeric(12,4), created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, provider_id uuid not null, model_code varchar(100) not null, display_name varchar(150), primary key (id));
create table ai_providers (enabled boolean not null, created_at timestamp(6) not null, deleted_at timestamp(6), free_tier_detected_at timestamp(6), last_tested_at timestamp(6), model_catalog_synced_at timestamp(6), updated_at timestamp(6), id uuid not null, code varchar(30) not null check ((code in ('ANTHROPIC','GOOGLE','UNKNOWN'))), last_test_status varchar(30) check ((last_test_status in ('SUCCESS','FAILED','OK','INVALID_KEY','RATE_LIMITED','DAILY_QUOTA_EXHAUSTED','PROVIDER_OVERLOADED','NETWORK_ERROR'))), name varchar(100) not null, api_key text, model_catalog jsonb, primary key (id));
create table ai_task_routing (enabled boolean not null, max_tokens integer, temperature float(53), created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), fallback_model_id uuid, id uuid not null, primary_model_id uuid not null, task_code varchar(40) not null check ((task_code in ('CONTENT_GENERATION','PLATFORM_FORMATTING','TREND_RESEARCH','GOLDEN_HOURS','STRATEGY_OPTIMIZATION','CONTENT_REGENERATION'))), primary key (id));
create table ai_task_routing_fallback (position integer not null, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, model_id uuid not null, routing_id uuid not null, primary key (id), constraint uk_ai_routing_fallback_position unique (routing_id, position), constraint uk_ai_routing_fallback_model unique (routing_id, model_id));
create table ai_usage (estimated_cost numeric(14,6), billing_period varchar(7), billable_units bigint, cached_tokens bigint, created_at timestamp(6) not null, credit_shortfall bigint, credit_units bigint, deleted_at timestamp(6), input_tokens bigint, latency_ms bigint, output_tokens bigint, total_tokens bigint not null, updated_at timestamp(6), status varchar(10) check ((status in ('SUCCESS','ERROR','TIMEOUT'))), id uuid not null, request_id uuid, user_id uuid, plan_at_time varchar(20), provider_code varchar(30) not null check ((provider_code in ('ANTHROPIC','GOOGLE','UNKNOWN'))), task_code varchar(40) not null check ((task_code in ('CONTENT_GENERATION','PLATFORM_FORMATTING','TREND_RESEARCH','GOLDEN_HOURS','STRATEGY_OPTIMIZATION','CONTENT_REGENERATION'))), client_ip varchar(45), model_code varchar(100) not null, routed_model_code varchar(100), idempotency_key varchar(120), user_agent varchar(300), primary key (id));
create table billing_rates (multiplier numeric(12,6) not null, created_at timestamp(6) not null, deleted_at timestamp(6), effective_from timestamp(6) not null, effective_to timestamp(6), min_charge bigint, updated_at timestamp(6), created_by uuid, id uuid not null, unit_type varchar(20) not null check ((unit_type in ('TOKEN_TOTAL','TOKEN_IN','TOKEN_OUT','REQUEST','IMAGE','SECOND'))), task_code varchar(40) check ((task_code in ('CONTENT_GENERATION','PLATFORM_FORMATTING','TREND_RESEARCH','GOLDEN_HOURS','STRATEGY_OPTIMIZATION','CONTENT_REGENERATION'))), model_code varchar(100), primary key (id));
create table brand_profile_donts (brand_profile_id uuid not null, dont_item varchar(150));
create table brand_profile_dos (brand_profile_id uuid not null, do_item varchar(150));
create table brand_profile_keywords (brand_profile_id uuid not null, keyword varchar(100));
create table brand_profile_platforms (brand_profile_id uuid not null, platform varchar(20) check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))));
create table brand_profiles (brand_health_score integer, is_active boolean not null, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, user_id uuid not null, industry varchar(100) not null, brand_name varchar(150) not null, description text, logo_url varchar(500), target_audience varchar(500) not null, brand_voice varchar(255), content_goal text, primary key (id));
create table content_formatting_jobs (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), content_item_id uuid not null, id uuid not null, status varchar(20) not null check ((status in ('PENDING','RUNNING','SUCCESS','FAILED'))), client_ip varchar(45), platforms varchar(100) not null, user_agent varchar(300), error_message text, primary key (id));
create table content_generation_jobs (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), content_item_id uuid, content_strategy_id uuid not null, id uuid not null, idea_id uuid, result_content_version_id uuid, trend_id uuid, platform varchar(20) not null check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))), status varchar(20) not null check ((status in ('PENDING','RUNNING','SUCCESS','FAILED'))), error_code varchar(40), client_ip varchar(45), idempotency_key varchar(64), user_agent varchar(300), error_message text, note text, regenerate_from text, topic text, primary key (id));
create table content_ideas (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, trend_id uuid not null, platform varchar(20) not null check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))), suitability_level varchar(20) check ((suitability_level in ('LOW','MEDIUM','HIGH'))), idea_description text, idea_title varchar(255) not null, primary key (id));
create table content_items (wizard_step integer, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), brand_profile_id uuid not null, content_idea_id uuid, id uuid not null, trend_id uuid, status varchar(20) not null check ((status in ('DRAFT','GENERATED','NEED_REVIEW','APPROVED','FORMATTED','SCHEDULED','POSTING','POSTED','FAILED','ANALYZING','OPTIMIZED'))), wizard_platforms varchar(100), caption text, cta varchar(255), hashtag text, media_prompt text, script text, wizard_note text, primary key (id));
create table content_regeneration_jobs (step_index integer, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), field varchar(10) not null check ((field in ('CONTENT','SCENE'))), section varchar(10) not null check ((section in ('HOOK','BODY','CTA'))), content_version_id uuid not null, id uuid not null, status varchar(20) not null check ((status in ('PENDING','RUNNING','SUCCESS','FAILED'))), client_ip varchar(45), user_agent varchar(300), error_message text, result_patch text, primary key (id));
create table content_strategies (posts_per_week integer not null, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), frequency_unit varchar(10), brand_profile_id uuid not null, id uuid not null, status varchar(20) not null check ((status in ('DRAFT','ACTIVE','PAUSED'))), name varchar(150) not null, primary key (id));
create table content_strategy_content_types (content_strategy_id uuid not null, content_type varchar(150));
create table content_strategy_cta_types (content_strategy_id uuid not null, cta_type varchar(150));
create table content_strategy_goals (content_strategy_id uuid not null, goal varchar(150));
create table content_strategy_platforms (content_strategy_id uuid not null, platform varchar(20) check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))));
create table content_strategy_styles (content_strategy_id uuid not null, style varchar(150));
create table content_strategy_target_audience (content_strategy_id uuid not null, audience varchar(150));
create table content_strategy_time_slots (content_strategy_id uuid not null, time_slot varchar(30));
create table content_versions (voice_aligned boolean, voice_score integer, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), content_item_id uuid not null, id uuid not null, source_version_id uuid, media_format varchar(20), platform_name varchar(20) not null check ((platform_name in ('FACEBOOK','INSTAGRAM','THREADS'))), status varchar(20) not null check ((status in ('DRAFT','GENERATED','NEED_REVIEW','APPROVED','FORMATTED','SCHEDULED','POSTING','POSTED','FAILED','ANALYZING','OPTIMIZED'))), cta varchar(255), formatted_caption text, formatted_hashtag text, image_prompt text, media_prompt text, script text, voice_notes text, primary key (id));
create table landing_sections (created_at timestamp(6) not null, deleted_at timestamp(6), published_at timestamp(6), updated_at timestamp(6), version bigint not null, id uuid not null, section_key varchar(40) not null, published_by varchar(255), updated_by varchar(255), draft_content jsonb not null, published_content jsonb not null, primary key (id), constraint uk_landing_sections_key unique (section_key));
create table media_assets (duration integer, created_at timestamp(6) not null, deleted_at timestamp(6), size bigint, updated_at timestamp(6), content_item_id uuid not null, id uuid not null, format varchar(20), media_type varchar(20) not null check ((media_type in ('IMAGE','VIDEO','PROMPT'))), media_url varchar(500), media_prompt text, primary key (id));
create table meta_data_deletion_requests (connections_removed integer not null, schedules_held integer not null, completed_at timestamp(6), created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, confirmation_code varchar(40) not null unique, primary key (id));
create table notifications (created_at timestamp(6) not null, deleted_at timestamp(6), read_at timestamp(6), updated_at timestamp(6), id uuid not null, ref_id uuid, user_id uuid not null, type varchar(30) not null check ((type in ('POST_PUBLISHED','POST_FAILED','REVIEW_NEEDED','RECONNECT_NEEDED','NEW_INSIGHT','PAYMENT_SUCCEEDED','PLAN_EXPIRED','PAYMENT_WEBHOOK_ALERT'))), message text, title varchar(255) not null, primary key (id));
create table optimization_insights (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), analytics_id uuid not null, id uuid not null, insight_content text not null, recommendation text, primary key (id));
create table payments (currency varchar(3) not null, expiry_grace_count integer not null default 0 not null, proration_cycle_days integer, proration_remaining_days integer, reconcile_required boolean not null default false not null, amount bigint not null, created_at timestamp(6) not null, deleted_at timestamp(6), expires_at timestamp(6), from_expires_at timestamp(6), list_price bigint, ordered_at timestamp(6) not null, paid_at timestamp(6), period_end timestamp(6), period_start timestamp(6), proration_credit bigint, proration_rounding bigint, refunded_amount bigint not null, refunded_at timestamp(6), updated_at timestamp(6), id uuid not null, plan_id uuid not null, user_id uuid, gateway varchar(20) not null check ((gateway in ('MANUAL','PAYOS','MOCK'))), order_type varchar(20) check ((order_type in ('NEW','RENEW','UPGRADE'))), payment_method varchar(30) check ((payment_method in ('PAYOS_VIETQR'))), status varchar(30) not null check ((status in ('PENDING','PAID','FAILED','EXPIRED','CANCELLED','REFUNDED','PARTIALLY_REFUNDED'))), from_plan_code varchar(50), invoice_no varchar(50), gateway_link_id varchar(100), gateway_txn_id varchar(100), checkout_url varchar(500), failed_reason varchar(500), note varchar(500), raw_payload TEXT, primary key (id));
create table plan_feature_values (bool_value boolean, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), feature_id uuid not null, id uuid not null, plan_id uuid not null, text_en varchar(200), text_vi varchar(200), primary key (id), constraint uk_plan_feature_values_feature_plan unique (feature_id, plan_id));
create table plan_features (display_order integer not null, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, group_en varchar(100), group_vi varchar(100), name_en varchar(200) not null, name_vi varchar(200) not null, primary key (id));
create table plans (billing_interval_months smallint not null default 1 not null, display_order integer not null, highlight boolean not null, is_active boolean not null, created_at timestamp(6) not null, deleted_at timestamp(6), monthly_token_limit bigint, price bigint not null, token_quota bigint, updated_at timestamp(6), id uuid not null, code varchar(20) not null, billing_cycle_en varchar(50), billing_cycle_vi varchar(50), cta_en varchar(100), cta_vi varchar(100), name_en varchar(100) not null, name_vi varchar(100) not null, description_en varchar(500), description_vi varchar(500), features_en TEXT, features_vi TEXT, teaser_features_en TEXT, teaser_features_vi TEXT, primary key (id));
create table platform_accounts (created_at timestamp(6) not null, deleted_at timestamp(6), last_sync_at timestamp(6), last_validated_at timestamp(6), token_expired_at timestamp(6), token_issued_at timestamp(6), updated_at timestamp(6), id uuid not null, parent_connection_id uuid, user_id uuid not null, api_version_used varchar(20), connection_status varchar(20) not null check ((connection_status in ('CONNECTED','DISCONNECTED','EXPIRED','ON_HOLD','ACTIVE','REVOKED','ERROR','PENDING'))), platform_name varchar(20) not null check ((platform_name in ('FACEBOOK','INSTAGRAM','THREADS'))), account_type varchar(30) not null check ((account_type in ('USER','PAGE','BUSINESS_ACCOUNT','PERSONAL'))), token_type varchar(30) not null check ((token_type in ('USER_TOKEN','PAGE_TOKEN','LONG_LIVED_USER_TOKEN'))), platform_account_id varchar(100) not null, account_name varchar(150) not null, platform_username varchar(150), avatar_url varchar(2048), profile_url varchar(2048), access_token text not null, refresh_token text, scopes text, metadata jsonb, primary key (id));
create table platform_api_version_history (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), changed_by uuid, id uuid not null, platform_api_version_id uuid not null, from_version varchar(20), to_version varchar(20), change_type varchar(30) not null check ((change_type in ('MANUAL_UPDATE','AUTO_DETECTED','ROLLBACK'))), notes text, primary key (id));
create table platform_api_versions (created_at timestamp(6) not null, current_version_deprecation_date timestamp(6), deleted_at timestamp(6), last_checked_at timestamp(6), updated_at timestamp(6), id uuid not null, updated_by uuid, current_version varchar(20) not null, latest_version varchar(20), min_supported_version varchar(20), platform varchar(20) not null check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))), status varchar(30) not null check ((status in ('UP_TO_DATE','UPDATE_AVAILABLE','DEPRECATING_SOON','DEPRECATED'))), primary key (id), constraint uk_platform_api_versions_platform unique (platform));
create table post_analytics (conversion numeric(7,4), ctr numeric(7,4), milestone_hours integer, collected_at timestamp(6) not null, comments bigint, created_at timestamp(6) not null, deleted_at timestamp(6), likes bigint, saves bigint, shares bigint, updated_at timestamp(6), views bigint, watch_time bigint, id uuid not null, post_id uuid not null, primary key (id));
create table post_schedules (created_at timestamp(6) not null, deleted_at timestamp(6), scheduled_time timestamp(6) not null, updated_at timestamp(6), content_version_id uuid not null unique, id uuid not null, platform_account_id uuid not null, status varchar(20) not null check ((status in ('SCHEDULED','ON_HOLD','POSTING','POSTED','FAILED','CANCELLED'))), primary key (id));
create table posting_jobs (retry_count integer not null, created_at timestamp(6) not null, deleted_at timestamp(6), end_time timestamp(6), next_retry_at timestamp(6), start_time timestamp(6), updated_at timestamp(6), id uuid not null, post_id uuid not null, error_type varchar(20) check ((error_type in ('TEMPORARY','PERMANENT','POLICY_VIOLATION','INTERNAL'))), status varchar(20) not null check ((status in ('PENDING','RUNNING','SUCCESS','FAILED','RETRYING'))), error_message text, primary key (id));
create table posts (created_at timestamp(6) not null, deleted_at timestamp(6), published_at timestamp(6), updated_at timestamp(6), id uuid not null, schedule_id uuid not null unique, platform_name varchar(20) not null check ((platform_name in ('FACEBOOK','INSTAGRAM','THREADS'))), status varchar(20) not null check ((status in ('POSTING','POSTED','FAILED'))), platform_post_id varchar(255), primary key (id));
create table publish_results (is_success boolean not null, created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, post_id uuid not null, response_code varchar(50), response_message text, primary key (id));
create table roles (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, description varchar(1000), role_name varchar(255) not null unique, primary key (id));
create table strategy_adjustments (created_at timestamp(6) not null, decided_at timestamp(6), deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, insight_id uuid not null, strategy_id uuid not null, applied_status varchar(20) not null check ((applied_status in ('PENDING','APPLIED','REJECTED'))), adjustment_content text not null, rationale text, primary key (id));
create table strategy_optimization_jobs (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), content_strategy_id uuid not null, id uuid not null, status varchar(20) not null check ((status in ('PENDING','RUNNING','SUCCESS','FAILED'))), client_ip varchar(45), user_agent varchar(300), error_message text, future_improvements text, primary key (id));
create table subscription_history (extend_amount integer, created_at timestamp(6) not null, deleted_at timestamp(6), from_expires_at timestamp(6), to_expires_at timestamp(6), updated_at timestamp(6), extend_unit varchar(10) check ((extend_unit in ('DAY','WEEK','MONTH'))), actor_user_id uuid, id uuid not null, user_id uuid not null, category varchar(20) check ((category in ('PROMOTION','COMPENSATION','SUPPORT','OTHER'))), from_source varchar(20) check ((from_source in ('FREE','PAYMENT','ADMIN'))), to_source varchar(20) check ((to_source in ('FREE','PAYMENT','ADMIN'))), action varchar(30) not null check ((action in ('PAYMENT_ACTIVATED','ADMIN_EXTENDED','ADMIN_CHANGED','ADMIN_REVOKED','EXPIRED'))), from_plan_code varchar(50), to_plan_code varchar(50), reason varchar(500), actor_email varchar(255), primary key (id));
create table subscriptions (created_at timestamp(6) not null, current_period_end timestamp(6) not null, current_period_start timestamp(6) not null, deleted_at timestamp(6), plan_expires_at timestamp(6), plan_started_at timestamp(6), updated_at timestamp(6), id uuid not null, plan_id uuid not null, user_id uuid not null, plan_source varchar(20) not null default 'FREE' not null check ((plan_source in ('FREE','PAYMENT','ADMIN'))), status varchar(20) not null check ((status in ('ACTIVE','PENDING','CANCELLED','EXPIRED'))), primary key (id));
create table system_logs (created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), level varchar(10) not null check ((level in ('ERROR','WARN','INFO','DEBUG'))), id uuid not null, module varchar(100) not null, detail text, message text not null, primary key (id));
create table token_credits (created_at timestamp(6) not null, deleted_at timestamp(6), expires_at timestamp(6), tokens_consumed bigint not null, tokens_granted bigint not null, updated_at timestamp(6), status varchar(10) not null check ((status in ('ACTIVE','REVOKED'))), id uuid not null, payment_id uuid, user_id uuid not null, note varchar(300), primary key (id));
create table trend_research_sessions (article_count integer, created_at timestamp(6) not null, deleted_at timestamp(6), research_time timestamp(6) not null, updated_at timestamp(6), brand_profile_id uuid not null, content_strategy_id uuid, id uuid not null, platform varchar(20) not null check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))), status varchar(20) not null check ((status in ('PENDING','RUNNING','COMPLETED','FAILED'))), client_ip varchar(45), industry varchar(100) not null, user_agent varchar(300), error_message text, summary text, primary key (id));
create table trends (relevance_score numeric(5,2), created_at timestamp(6) not null, deleted_at timestamp(6), updated_at timestamp(6), id uuid not null, research_session_id uuid not null, platform varchar(20) not null check ((platform in ('FACEBOOK','INSTAGRAM','THREADS'))), description text, trend_name varchar(255) not null, primary key (id));
create table usage_adjustments (billing_period varchar(7) not null, created_at timestamp(6) not null, deleted_at timestamp(6), delta_tokens bigint, updated_at timestamp(6), type varchar(10) not null check ((type in ('GRANT','RESET'))), actor_user_id uuid, id uuid not null, payment_id uuid, user_id uuid not null, source varchar(20) not null check ((source in ('ADMIN_GRANT','PURCHASE','PROMO'))), reason varchar(500), primary key (id));
create table usage_alerts (false_positive boolean, acked_at timestamp(6), cooldown_until timestamp(6), created_at timestamp(6) not null, deleted_at timestamp(6), first_seen timestamp(6) not null, last_seen timestamp(6) not null, occurrence_count bigint not null, updated_at timestamp(6), severity varchar(10) not null check ((severity in ('INFO','WARNING','CRITICAL'))), status varchar(10) not null check ((status in ('OPEN','ACKED'))), id uuid not null, user_id uuid, rule_code varchar(30) not null check ((rule_code in ('HIGH_REQUEST_RATE','QUOTA_BURST','DAILY_SPIKE','MULTI_CLIENT','SYSTEM_ERROR_RATE','USER_COST','CREDIT_SHORTFALL','ADMIN_GRANT_ANOMALY','SYSTEM_COST'))), acked_by_email varchar(200), user_email varchar(200), message varchar(500) not null, data text, primary key (id));
create table usage_daily (cost_usd numeric(14,6), billable_units bigint, created_at timestamp(6) not null, credit_units bigint, day_bucket timestamp(6) not null, deleted_at timestamp(6), errors bigint not null, latency_count bigint, latency_sum_ms bigint, requests bigint not null, total_tokens bigint, updated_at timestamp(6), id uuid not null, user_id uuid, provider_code varchar(30) not null check ((provider_code in ('ANTHROPIC','GOOGLE','UNKNOWN'))), task_code varchar(40) not null check ((task_code in ('CONTENT_GENERATION','PLATFORM_FORMATTING','TREND_RESEARCH','GOLDEN_HOURS','STRATEGY_OPTIMIZATION','CONTENT_REGENERATION'))), model_code varchar(100) not null, primary key (id));
create table usage_hourly (cost_usd numeric(14,6), billable_units bigint, created_at timestamp(6) not null, credit_units bigint, deleted_at timestamp(6), errors bigint not null, hour_bucket timestamp(6) not null, latency_count bigint, latency_sum_ms bigint, requests bigint not null, total_tokens bigint, updated_at timestamp(6), id uuid not null, user_id uuid, provider_code varchar(30) not null check ((provider_code in ('ANTHROPIC','GOOGLE','UNKNOWN'))), task_code varchar(40) not null check ((task_code in ('CONTENT_GENERATION','PLATFORM_FORMATTING','TREND_RESEARCH','GOLDEN_HOURS','STRATEGY_OPTIMIZATION','CONTENT_REGENERATION'))), model_code varchar(100) not null, primary key (id));
create table users (date_of_birth date, profile_completed boolean, token_usage_month varchar(7), created_at timestamp(6) not null, deleted_at timestamp(6), deletion_date timestamp(6), deletion_warning_sent_at timestamp(6), last_active_at timestamp(6), last_password_change_at timestamp(6), tokens_used bigint, updated_at timestamp(6), id uuid not null, role_id uuid not null, plan varchar(20) check ((plan in ('FREE','PLUS','PRO'))), provider varchar(20), full_name varchar(100) not null, avatar_url varchar(500), email varchar(255) not null unique, google_id varchar(255) unique, password varchar(255), phone varchar(255), status varchar(255) not null check ((status in ('ACTIVE','LOCKED','PENDING_DELETE'))), user_name varchar(255) not null unique, primary key (id));
create index idx_activity_logs_created_at on activity_logs (created_at desc);
create index idx_activity_logs_user_created on activity_logs (user_id, created_at desc);
create index idx_activity_logs_action_created on activity_logs (action, created_at desc);
create index idx_ai_config_audit_entity on ai_config_audit (entity_type, entity_id);
create index idx_ai_config_audit_created_at on ai_config_audit (created_at);
create index idx_ai_model_price_catalog_model on ai_model_price_catalog (provider_code, model_code);
create index idx_ai_models_provider_model on ai_models (provider_id, model_code);
create index idx_ai_task_routing_task_code on ai_task_routing (task_code);
create index idx_ai_routing_fallback_model on ai_task_routing_fallback (model_id);
create index idx_ai_usage_user on ai_usage (user_id);
create index idx_ai_usage_task_code on ai_usage (task_code);
create index idx_ai_usage_created_at on ai_usage (created_at);
