ALTER TABLE payments ALTER COLUMN user_id DROP NOT NULL;
CREATE INDEX IF NOT EXISTS idx_payments_status_paid_at ON payments (status, paid_at DESC);
CREATE INDEX IF NOT EXISTS idx_payments_refunded_at ON payments (refunded_at) WHERE refunded_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_payments_plan_paid_at ON payments (plan_id, paid_at DESC);
CREATE INDEX IF NOT EXISTS idx_payments_ordered_at ON payments (ordered_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uk_payments_gateway_txn ON payments (gateway_txn_id) WHERE gateway_txn_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_payments_user_ordered ON payments (user_id, ordered_at DESC);
CREATE INDEX IF NOT EXISTS idx_payments_pending_expiry ON payments (expires_at) WHERE status = 'PENDING' AND deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_payments_one_pending_per_user ON payments (user_id) WHERE status = 'PENDING' AND deleted_at IS NULL AND gateway <> 'MANUAL';
UPDATE payments SET expiry_grace_count = 0 WHERE expiry_grace_count IS NULL;
UPDATE payments SET reconcile_required = false WHERE reconcile_required IS NULL;
UPDATE subscriptions SET plan_source = 'FREE' WHERE plan_source IS NULL;
CREATE INDEX IF NOT EXISTS idx_subscriptions_plan_expires ON subscriptions (plan_expires_at) WHERE plan_expires_at IS NOT NULL;
COMMENT ON COLUMN payments.paid_at IS 'Moc thu duoc tien, GIO VIET NAM (LocalDateTime theo APP_TIMEZONE) — quy ky cho phan GOP cua doanh thu. APP_TIMEZONE la HANG SO sau khi co du lieu (xem TimezoneVerificationConfig)';
COMMENT ON COLUMN payments.refunded_at IS 'Moc phat sinh hoan tien — quy ky cho phan TRU. Tach khoi paid_at de doanh thu ky da dong so KHONG bi thay doi khi hoan tien ve sau (cong thuc net, khong hoi to — chot 2026-07-20)';
COMMENT ON COLUMN payments.ordered_at IS 'Moc TAO DON (thoi diem nghiep vu, GIO VIET NAM) — tach khoi created_at la cot audit. Dung de quy ky cho don PENDING/FAILED va de doi soat voi moc don cua cong thanh toan';
COMMENT ON COLUMN payments.gateway_txn_id IS 'Ma giao dich phia cong (payOS: orderCode dang chuoi). Partial unique = khoa idempotency cho webhook bi gui lap';
COMMENT ON COLUMN payments.expires_at IS 'Han chot thanh toan. MOT moc duy nhat cho ca dem nguoc hien cho user LAN expiredAt (Unix giay) gui cho payOS luc tao link — tinh mot lan luc tao don roi dung lai cho ca hai';
COMMENT ON COLUMN payments.reconcile_required IS 'Can DOI SOAT TAY: tien ve sau khi don da het han/huy, so tien lech (payOS UNDERPAID van gui webhook code=00), cong tra trang thai la, hoac khong xac nhan duoc trang thai that cua link';
COMMENT ON COLUMN subscriptions.plan_expires_at IS 'Moc het han GOI TRA TIEN — NULL = khong het han (goi Free/admin cap vinh vien), KHONG phai het han ngay. Khac han current_period_end la moc reset HAN MUC TOKEN theo thang lich';
COMMENT ON COLUMN subscriptions.plan_source IS 'Vi sao user dang o goi nay: FREE | PAYMENT (co dong payments da PAID) | ADMIN (cap tay, luon kem ly do trong activity_logs). Goi ADMIN khong co doanh thu tuong ung';
CREATE INDEX IF NOT EXISTS idx_ai_usage_created_id ON ai_usage (created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS idx_ai_usage_user_created ON ai_usage (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ai_usage_task_created ON ai_usage (task_code, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_usage_idempotency ON ai_usage (idempotency_key) WHERE idempotency_key IS NOT NULL;
COMMENT ON COLUMN usage_hourly.hour_bucket IS 'date_trunc(hour, created_at) tren timestamp luu GIO VIET NAM (JDBC ghi LocalDateTime theo APP_TIMEZONE=Asia/Ho_Chi_Minh) — bucket 03:00 = 3h sang gio VN, khong phai UTC. APP_TIMEZONE la HANG SO sau khi co du lieu (khong cot nao luu timezone luc ghi) — doi = migration co ke hoach, guard o TimezoneVerificationConfig/system_config';
COMMENT ON COLUMN usage_daily.day_bucket IS 'date_trunc(day, created_at) theo GIO VIET NAM — cung quy uoc voi usage_hourly.hour_bucket (APP_TIMEZONE la hang so, xem comment o do)';
COMMENT ON COLUMN ai_usage.created_at IS 'Timestamp GIO VIET NAM (LocalDateTime theo APP_TIMEZONE) — APP_TIMEZONE la HANG SO sau khi co du lieu, doi = migration co ke hoach';
UPDATE platform_accounts SET api_version_used = 'v25.0' WHERE api_version_used IS NULL;
UPDATE platform_accounts SET account_type = 'USER' WHERE account_type IS NULL;
UPDATE platform_accounts SET token_type = 'USER_TOKEN' WHERE token_type IS NULL;
UPDATE platform_accounts SET platform_account_id = id::text WHERE platform_account_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_platform_accounts_user_platform_account ON platform_accounts (user_id, platform_name, platform_account_id) WHERE deleted_at IS NULL;
UPDATE plans SET billing_interval_months = 1 WHERE billing_interval_months IS NULL OR billing_interval_months < 1;
ALTER TABLE plans DROP CONSTRAINT IF EXISTS plans_billing_interval_months_check;
ALTER TABLE plans ADD CONSTRAINT plans_billing_interval_months_check CHECK (billing_interval_months >= 1 AND billing_interval_months <= 60);
ALTER TABLE ai_providers ALTER COLUMN last_test_status TYPE varchar(30);
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_providers_code ON ai_providers (code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_models_provider_model ON ai_models (provider_id, model_code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_task_routing_task_code ON ai_task_routing (task_code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_ai_model_price_catalog ON ai_model_price_catalog (provider_code, model_code) WHERE deleted_at IS NULL;
CREATE TABLE shedlock (name varchar(64) PRIMARY KEY, lock_until timestamp NOT NULL, locked_at timestamp NOT NULL, locked_by varchar(255) NOT NULL);
CREATE TABLE system_config (config_key varchar(100) PRIMARY KEY, config_value varchar(300) NOT NULL, updated_at timestamp NOT NULL DEFAULT now());
INSERT INTO system_config(config_key, config_value) VALUES ('app.timezone', 'Asia/Ho_Chi_Minh');
